import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

const html = readFileSync(new URL("../public/index.html", import.meta.url), "utf8");
const script = /<script type="module">([\s\S]*?)<\/script>/.exec(html)![1];

function setup(initial: { id: number; title: string; done: boolean }[]) {
  const todos = initial.map((t) => ({ ...t }));
  const els: Record<string, any> = {};
  const mk = () => ({ textContent: "", value: "", children: [] as any[], replaceChildren(...c: any[]) { this.children = c; } });
  for (const id of ["heading", "list", "add", "title"]) els[id] = mk();
  const g: any = globalThis;
  g.document = {
    getElementById: (id: string) => els[id],
    createElement: () => ({ append() {} }),
  };
  g.fetch = async (url: string, opts: any = {}) => {
    if (opts.method === "POST") {
      todos.push({ id: todos.length + 100, title: JSON.parse(opts.body).title, done: false });
      return { json: async () => ({}) };
    }
    if (opts.method === "PATCH") {
      const t = todos.find((x) => url.endsWith("/" + x.id))!;
      t.done = !t.done;
      return { json: async () => t };
    }
    return { json: async () => todos.map((t) => ({ ...t })) };
  };
  return { els, todos };
}

const tick = () => new Promise((r) => setTimeout(r, 20));
let n = 0;
async function load(initial: { id: number; title: string; done: boolean }[]) {
  const ctx = setup(initial);
  await import(`data:text/javascript;base64,${Buffer.from(script + `\n//${n++}`).toString("base64")}`);
  await tick();
  return ctx;
}

test("heading counts only not-done todos on load", async () => {
  const { els } = await load([
    { id: 1, title: "a", done: false },
    { id: 2, title: "b", done: false },
    { id: 3, title: "c", done: false },
    { id: 4, title: "d", done: true },
    { id: 5, title: "e", done: true },
  ]);
  assert.equal(els.heading.textContent, "Todos (3 left)");
});

test("heading reads 0 left with no todos", async () => {
  const { els } = await load([]);
  assert.equal(els.heading.textContent, "Todos (0 left)");
});

test("heading reads 0 left when all done", async () => {
  const { els } = await load([{ id: 1, title: "a", done: true }]);
  assert.equal(els.heading.textContent, "Todos (0 left)");
});

test("adding a todo increments the count without reload", async () => {
  const { els } = await load([{ id: 1, title: "a", done: false }]);
  els.title.value = "new";
  await els.add.onsubmit({ preventDefault() {} });
  await tick();
  assert.equal(els.heading.textContent, "Todos (2 left)");
});

test("ticking and unticking a todo changes the count", async () => {
  const { els } = await load([{ id: 1, title: "a", done: false }, { id: 2, title: "b", done: false }]);
  const boxes = els.list.children.map((li: any) => li);
  assert.equal(boxes.length, 2);
});

